class BSTIterator:
    def __init__(self, root):
        self.vals, self.i = [], 0      # the whole in-order up front: O(n) memory

        def inorder(node):
            if node:
                inorder(node.left)
                self.vals.append(node.val)
                inorder(node.right)

        inorder(root)

    def next(self):
        self.i += 1
        return self.vals[self.i - 1]

    def hasNext(self):
        return self.i < len(self.vals)

