def get_minimum_difference(root):
    vals = []

    def collect(node):                 # any order: the BST property is unused
        if node:
            vals.append(node.val)
            collect(node.left)
            collect(node.right)

    collect(root)
    vals.sort()
    return min(b - a for a, b in zip(vals, vals[1:]))

